(()=>{
 'use strict';
 const $=s=>document.querySelector(s),A=KanjiStudyCohort,records=new Map(),reviews=new Map();let selected=null;
 const familiarity={none:'Chưa biết tiếng Nhật',beginner:'Mới học tiếng Nhật',unspecified:'Chưa xác định'};
 const notesKey=id=>'kanji-pop-study-review-'+id;
 function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
 function safeReview(x){const result={};if(!x||typeof x!=='object')return result;for(const k of ['movement','halo','credit'])result[k]=['understood','unclear','unobserved'].includes(x[k])?x[k]:'unobserved';result.ending=['continued','chose_stop','time_limit','technical','unobserved'].includes(x.ending)?x.ending:'unobserved';for(const k of ['device','friction','recallNow','recallLater'])result[k]=typeof x[k]==='string'?x[k].slice(0,k==='device'?100:1500):'';result.updatedAt=typeof x.updatedAt==='string'?x.updatedAt:'';return result;}
 function reviewFor(id){if(reviews.has(id))return reviews.get(id);try{const r=safeReview(JSON.parse(localStorage.getItem(notesKey(id))));reviews.set(id,r);return r;}catch{return {};}}
 function render(){
  const c=A.cohort(records.values());$('#metrics').replaceChildren();
  for(const [value,label] of [[c.sessions,'phiên riêng · không phải số người đã xác minh'],[c.observedThreeLevelCompletions,'phiên có ghi nhận hoàn thành 3 màn đầu'],[c.firstMatchMedianMs===null?'—':(c.firstMatchMedianMs/1000).toFixed(1)+' s','trung vị ghép đầu · '+c.firstMatchSampleCount+' phiên đủ dữ liệu'],[c.partialSessions,'phiên có dữ liệu chưa đầy đủ']]){const card=node('div',undefined,'metric');card.append(node('strong',String(value)),node('small',label));$('#metrics').append(card);}
  $('#sessions').replaceChildren();if(!c.rows.length)$('#sessions').append(node('p','Chưa có phiên thử riêng. Mở game để tạo phiên, hoặc nhập JSON đã xuất.'));
  for(const row of c.rows){const b=node('button',(row.id.length>18?row.id.slice(0,8)+'…'+row.id.slice(-6):row.id), 'session');b.type='button';b.setAttribute('aria-pressed',String(selected===row.id));b.append(node('small',familiarity[row.familiarity]+' · '+row.runs+' lượt chơi'+(row.partial?' · thiếu dữ liệu':'')));b.onclick=()=>{selected=row.id;render();};$('#sessions').append(b);}
  if(selected&&records.has(selected))detail(records.get(selected));
 }
 function optionSelect(name,label,choices,value){const wrap=node('label',label),select=node('select');select.name=name;for(const [v,t] of choices){const o=node('option',t);o.value=v;o.selected=v===value;select.append(o);}wrap.append(select);return wrap;}
 function detail(d){
  const area=$('#detail');area.className='panel';area.replaceChildren(node('h2','Phiên '+d.study.id),node('p',familiarity[d.study.familiarity]+' · '+(d.study.adultConsent?'Có xác nhận đồng ý ghi nhận':'Chưa có xác nhận đồng ý')));
  const link=node('a','Mở lại phiên này ↗');link.href='/?playtest='+encodeURIComponent(d.study.id);link.target='_blank';link.rel='noopener';area.append(link);
  const list=node('div',undefined,'facts');for(const r of d.summary.runs){list.append(node('p','Màn '+(r.level+1)+' · '+r.mode+' · '+r.moves+' lượt trượt · '+r.matches+' lần ghép · '+r.hints+' gợi ý · '+r.invalidActions+' thao tác chưa hợp lệ · '+r.anchorMoved+' lần bù dịch viên mục tiêu. '+(r.completed?'Đã ghi nhận hoàn thành.':'Chưa ghi nhận hoàn thành.')));}if(!d.summary.runs.length)list.textContent='Chưa có lượt chơi được ghi nhận.';area.append(list);
  area.append(node('h3','Nhận xét do người chơi nhập'));
  if(!d.observations.length)area.append(node('p','Chưa có nhận xét.'));
  for(const o of d.observations)area.append(node('p','Mức dễ hiểu: '+o.rating+'/5 · Chơi tiếp: '+({yes:'muốn',unsure:'chưa chắc',no:'không muốn'}[o.again])+'\nNhớ được: '+(o.recall||'chưa ghi'), 'observation'));
  const saved=reviewFor(d.study.id),form=node('form',undefined,'review');form.append(node('h3','Người điều phối ghi sau khi quan sát'),node('p','Hỏi bằng câu hỏi mở sau buổi chơi. Không chọn “đã hiểu” nếu chưa quan sát được.'));
  const options=[['unobserved','Chưa quan sát'],['understood','Tự giải thích đúng'],['unclear','Chưa hiểu hoặc cần giải thích']];
  for(const [key,label] of [['movement','Hiểu cách trượt vào ô trống'],['halo','Hiểu hào quang là gợi ý, được ghép cặp khác'],['credit','Hiểu thu đủ mục tiêu để qua màn']])form.append(optionSelect(key,label,options,saved[key]||'unobserved'));
  form.append(optionSelect('ending','Kết thúc buổi thử vì', [['unobserved','Chưa xác định'],['continued','Tự muốn chơi tiếp'],['chose_stop','Tự muốn dừng'],['time_limit','Hết thời gian buổi thử'],['technical','Gặp lỗi kỹ thuật']],saved.ending||'unobserved'));
  for(const [key,label] of [['device','Thiết bị thực tế (không ghi tên người)'],['friction','Điểm vướng hoặc cảm giác khi bàn bù khối'],['recallNow','Chữ/nghĩa tự nhớ sau nghỉ ngắn'],['recallLater','Chữ/nghĩa tự nhớ vào hôm sau (nếu đã hỏi)']]){const wrap=node('label',label),input=node(key==='device'?'input':'textarea');input.name=key;input.maxLength=key==='device'?100:1500;input.value=saved[key]||'';wrap.append(input);form.append(wrap);}
  const save=node('button','Lưu quan sát trên máy');save.type='submit';const status=node('p',undefined,'save-result');status.setAttribute('role','status');form.append(save,status);form.onsubmit=async e=>{e.preventDefault();const id=d.study.id,values=safeReview(Object.fromEntries(new FormData(form)));values.updatedAt=new Date().toISOString();save.disabled=true;try{if(!navigator.locks)throw Error('no-lock');await navigator.locks.request('kanji-pop:study-review:'+id,()=>localStorage.setItem(notesKey(id),JSON.stringify(values)));reviews.set(id,values);status.textContent='Đã lưu quan sát riêng; tiến trình game không thay đổi.';}catch{status.textContent='Chưa lưu được. Hãy giữ trang này, sao chép ghi chú và kiểm tra quyền lưu.';}finally{save.disabled=false;}};area.append(form);
 }
 function ingest(raw){const d=A.parse(raw);return A.merge(records,d);}
 $('#load-local').onclick=()=>{let count=0,rejected=0;try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key.startsWith('kanji-pop-experience-v1-study-'))continue;try{const data=JSON.parse(localStorage.getItem(key));if(!key.endsWith(data.study?.id))throw Error('id');ingest(JSON.stringify({...data,version:2,exportedAt:new Date().toISOString()}));count++;}catch{rejected++;}}$('#status').textContent='Đã đọc '+count+' phiên riêng trên máy; '+rejected+' bản không hợp lệ. Không đọc hoặc sửa save game chính.';}catch{$('#status').textContent='Trình duyệt không cho đọc lưu trữ. Bạn vẫn có thể nhập file JSON.';}render();};
 $('#import-files').onchange=async e=>{let added=0,updated=0,duplicate=0,conflict=0,failed=0;const files=[...e.target.files];if(files.length>100){$('#status').textContent='Chọn tối đa 100 file một lần.';return;}for(const file of files)try{if(file.size>2*1024*1024)throw Error('size');const status=ingest(await file.text());if(status==='added')added++;else if(status==='updated')updated++;else if(status==='conflict')conflict++;else duplicate++;}catch{failed++;}$('#status').textContent=added+' phiên mới · '+updated+' bản mới hơn · '+duplicate+' bản trùng/cũ bỏ qua · '+failed+' file không hợp lệ · '+conflict+' bản cùng thời điểm nhưng khác nội dung (giữ bản trước). Chưa ghi file nhập vào trình duyệt.';render();};
 $('#export-report').onclick=()=>{const summary=A.cohort(records.values()),payload=JSON.stringify({format:'kanji-pop-cohort',version:1,exportedAt:new Date().toISOString(),...summary,facilitatorReviews:[...records.keys()].map(id=>({studyId:id,...reviewFor(id)}))},null,2);$('#export-fallback').hidden=false;$('#export-json').value=payload;const a=node('a'),url=URL.createObjectURL(new Blob([payload],{type:'application/json'}));a.href=url;a.download='kanji-pop-cohort-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('#status').textContent='Đã yêu cầu tải tổng hợp. Có JSON dự phòng bên dưới để sao chép.';};
 $('#print-report').onclick=()=>window.print();render();
})();
